    ...switch (secretScanningPushProtectionCustomLinkEnabled) {
      SdkPresent<bool>(value: final value) => {'secret_scanning_push_protection_custom_link_enabled': value,},
      _ => const <String, dynamic>{},
    },
    ...switch (secretScanningPushProtectionCustomLink) {
      SdkPresent<String>(value: final value) => {'secret_scanning_push_protection_custom_link': value,},
      _ => const <String, dynamic>{},
    },
    ...switch (deployKeysEnabledForRepositories) {
      SdkPresent<bool>(value: final value) => {'deploy_keys_enabled_for_repositories': value,},
      _ => const <String, dynamic>{},
    },
  };
}
